:root {
  --bg-card: #ffffff;
  --bg-pro: #1e1b4b;
  --bg-pro-btn: #6366f1;
  --bg-tag: #6366f1;
  --border-default: #e2e8f0;
  --border-pro: #6366f1;
  --text-heading: #1e293b;
  --text-muted: #94a3b8;
  --text-pro: #ffffff;
  --text-pro-muted: #a5b4fc;
  --text-label: #64748b;
  --text-price: #1e293b;
  --text-on: #22c55e;
  --text-off: #cbd5e1;
  --text-tag: #ffffff;
  --badge-bg: #f1f5f9;
  --badge-text: #64748b;
  --btn-outline-border: #cbd5e1;
  --btn-outline-text: #475569;
  --btn-solid-text: #ffffff;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 16px;
  padding: 20px;
  width: 520px;
  max-width: 100%;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.label {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-heading);
}

.badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 99px;
}

.plans {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.plan {
  border: 1px solid var(--border-default);
  border-radius: 12px;
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
}

.plan--pro {
  background: var(--bg-pro);
  border-color: var(--border-pro);
}

.plan-tag {
  position: absolute;
  top: -11px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-tag);
  color: var(--text-tag);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 99px;
  white-space: nowrap;
}

.plan-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-label);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.plan--pro .plan-name {
  color: var(--text-pro-muted);
}

.plan-price {
  display: flex;
  align-items: baseline;
  gap: 2px;
}

.amount {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-price);
  line-height: 1;
}

.plan--pro .amount {
  color: var(--text-pro);
}

.period {
  font-size: 12px;
  color: var(--text-muted);
}

.plan--pro .period {
  color: var(--text-pro-muted);
}

.features {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.feature {
  font-size: 12px;
  font-weight: 500;
  padding-left: 18px;
  position: relative;
  line-height: 1.4;
}

.feature::before {
  content: "✓";
  position: absolute;
  left: 0;
  font-size: 11px;
}

.feature--on {
  color: var(--text-label);
}

.plan--pro .feature--on {
  color: var(--text-pro);
}

.feature--on::before {
  color: var(--text-on);
}

.feature--off {
  color: var(--text-off);
}

.feature--off::before {
  content: "✕";
  color: var(--text-off);
}

.plan--pro .feature--off {
  color: var(--text-pro-muted);
  opacity: 0.5;
}

.btn {
  width: 100%;
  padding: 8px 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  border: none;
  margin-top: 4px;
}

.btn--outline {
  background: transparent;
  border: 1.5px solid var(--btn-outline-border);
  color: var(--btn-outline-text);
}

.btn--solid {
  background: var(--bg-pro-btn);
  color: var(--btn-solid-text);
  border: none;
}
